// src/pages/ProductDetail.js
import React from "react";
import { useParams, Link } from "react-router-dom";
import "./ProductDetail.css";

import LD1 from "../assets/images/LD-250W.png";
import LD2 from "../assets/images/LD-250W_RF.png";
import LD3 from "../assets/images/LD-250W_BST.png";
import LD4 from "../assets/images/LD-RGB_BST.png";
import LD5 from "../assets/images/LD-RGB.png";
import DM1 from "../assets/images/DM-400LN.jpg";
import DM2 from "../assets/images/DM-1000W.jpg";
import DM3 from "../assets/images/DM-400B.png";
import DM4 from "../assets/images/DM-400B-RF.png";
import DM5 from "../assets/images/DM-300B.png";
import DM6 from "../assets/images/DM-DGL-B.png";
import DM7 from "../assets/images/DM-2500W.jpg";
import DM8 from "../assets/images/DM-2500.jpg";
import DM9 from "../assets/images/DM-PRO.jpg";

// ================== PRODUCT DATA ==================
const productData = {
  "ld-250w": {
    name: "LD-250W",
    image: LD1,
    description: (
      <>
        <p>
          <b>Led Controller LD-250W</b> was designed to fulfill the needs of
          illumination control and management of lighting fixtures using LED
          technology at <b>12VDC</b> and <b>24VDC</b> like Led Stripes, Led bulbs, etc. It is
          a safe and reliable product because it was designed with special
          integrated circuits and plastic parts for adverse operating
          conditions.
        </p>

        <p><br/>
          <b>Led Controller LD-250W operation features:</b>
        <br/></p>
        <ul>
          <li>
            Control from one or more parallel connected button to adjust
            lighting intensity (ON / OFF by briefly pressing the button and
            stretch the lighting - Dimming with a long press).
          </li>
          <li>
            Control through other systems and lighting regulators having
            communication protocol 1-10V.
          </li>
          <li>
            <b>Input:</b> 12 - 24V DC power supply
          </li>
          <li>
            <b>Output:</b> 12 - 24V DC / 21A to the electrical load.
          </li>
          <li>Function 12V / 250W operation 24V / 500W</li>
        </ul>

        <div className="technical-specs">
          <h3>Technical Specifications</h3>
          <p>FUNCTION: Soft - Start</p>
          <p>OPERATING VOLTAGE: 12-24V DC</p>
          <p>OUTPUT POWER: 250 Watt /12V & 500Watt /24V</p><br/>
          <p>CONTROL LOAD:</p>
          <ul>
            <li>LED lamps (dimmable)</li>
            <li>LED stripes</li>
            <li>Halogen lamps</li>
            <li>Resistive</li>
          </ul>
          <p>ENVIRONMENT TEMPERATURE: -20°C until +50°C</p>
          <p>
            FUSE: Electronic fuse for short-circuit protection with automatic
            reset
          </p>
          <p>WIRE SIZE: From Ø0.5 mm to Ø3.5 mm</p>
          <p>
            EUROPEAN COMMUNITY DIRECTIVES: The product complies with directives
            (LVD) 2014/35/EU and (EMC) 2014/30/EU
          </p>
        </div>
      </>
    ),
  },

  // ------- Example other products (you can keep yours as is) -------
  "ld-250w-rf": {
    name: "LD-250W-RF",
    image: LD2,
    description:
      "The LD-250W-RF is a radio-frequency LED dimmer designed for wireless illumination control. It supports RF remote communication, enabling convenient management of lighting fixtures in smart home and industrial environments.",
  },
  "ld-250w-bst": {
    name: "LD-250W-BST",
    image: LD3,
    description:
      "LD-250W-BST is a boosted power LED controller optimized for high-efficiency and longer LED life. It offers precise control for dimmable LED loads, suitable for professional lighting installations.",
  },
  "ld-rgb-bst": {
    name: "LD-RGB-BST",
    image: LD4,
    description:
      "LD-RGB-BST enables RGB LED control with boosted performance. It supports multiple color transitions and custom lighting effects, perfect for both residential and commercial applications.",
  },
  "ld-rgb": {
    name: "LD-RGB",
    image: LD5,
    description:
      "LD-RGB is an RGB LED controller designed to manage color transitions and brightness efficiently. Ideal for architectural, interior, and decorative lighting setups.",
  },
  "dm-400l-n": {
    name: "DM-400L/N",
    image: DM1,
    description:
      "The DM-400L/N wall-mounting dimmer provides precise brightness control for various lighting systems. It’s compact, efficient, and ideal for residential and office installations.",
  },
  "dm-1000w": {
    name: "DM-1000W",
    image: DM2,
    description:
      "DM-1000W is a high-capacity wall dimmer with a maximum load of 1000 watts. Designed for reliable and smooth dimming control with easy wall installation.",
  },
  "dm-400b": {
    name: "DM-400B",
    image: DM3,
    description:
      "The DM-400B flush-mount dimmer offers sleek integration with walls and panels, providing stable dimming performance for various lighting systems.",
  },
  "dm-400b-rf": {
    name: "DM-400B-RF",
    image: DM4,
    description:
      "DM-400B-RF includes wireless RF functionality for remote dimming control. It provides easy operation and stable performance for modern lighting solutions.",
  },
  "dm-300-b": {
    name: "DM-300/b",
    image: DM5,
    description:
      "The DM-300/b is a rail-mounted digital dimmer designed for industrial and commercial lighting control. Compact, safe, and easy to configure.",
  },
  "dm-dgl-b": {
    name: "DM-DGL/b",
    image: DM6,
    description:
      "DM-DGL/b provides advanced dimming control for LED fixtures, supporting multiple dimming protocols and secure installation on DIN rails.",
  },
  "dm-2500w": {
    name: "DM-2500W",
    image: DM7,
    description:
      "DM-2500W is a surface-mounting dimmer with high wattage handling for demanding lighting environments. Offers superior heat dissipation and stable operation.",
  },
  "dm-2500": {
    name: "DM-2500",
    image: DM8,
    description:
      "DM-2500 provides smooth dimming control for high-power LED or halogen fixtures, designed for long life and energy efficiency.",
  },
  "dm-pro-1-10v": {
    name: "DM-PRO 1-10V",
    image: DM9,
    description:
      "DM-PRO 1-10V supports analog 1-10V dimming control used in professional lighting systems. Offers superior compatibility and easy installation.",
  },
};

// ================== COMPONENT ==================
const ProductDetail = () => {
  const { productId } = useParams();
  const product = productData[productId];

  if (!product) {
    return (
      <div className="product-detail-container">
        <h2>Product Not Found</h2>
        <Link to="/k-watt-electric/products" className="back-button">
          Back to Products
        </Link>
      </div>
    );
  }

  return (
    <div className="product-detail-container">
      <div className="product-detail-content">
        <img src={product.image} alt={product.name} />
        <div className="product-detail-text">
          <h2>{product.name}</h2>

          {/* ✅ FIXED: use div, not p */}
          <div>{product.description}</div>

          <Link to="/products" className="back-button">
            ← Back to Products
          </Link>
        </div>
      </div>
    </div>
  );
};

export default ProductDetail;
